    background: #2c2c2e;
    border: none;
}
.mascot-container.hide-face .mascot-pupil { display: none; }
.mascot-container.hide-face .mascot-mouth {
    width: 10px;
    height: 10px;
    border: 3px solid #2c2c2e;
    border-radius: 50%;
    border-top-color: transparent;
    border-left-color: transparent;
    border-right-color: transparent;
    transform: translateY(-5px);
}

/* 登录卡片 */
.login-card {
    background: var(--card-bg);
    backdrop-filter: blur(24px) saturate(160%);
    -webkit-backdrop-filter: blur(24px) saturate(160%);
    border-radius: var(--radius-lg);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    width: 100%;
    max-width: 340px;
    padding: 36px 28px;
    box-sizing: border-box;
    border: 1px solid var(--card-border);
    position: relative;
    overflow: hidden;
}

.login-card::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle at 30% 20%, rgba(99, 102, 241, 0.06), transparent 60%);
    pointer-events: none;
}

.login-card h1 {
    text-align: center;
    margin: 0 0 28px 0;
    font-size: 26px;
    font-weight: 700;
    background: var(--primary-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: -0.5px;
}

.form-group { margin-bottom: 16px; }
.form-group input {
    width: 100%;
    padding: 14px 16px;
    border: 1px solid var(--card-border);
    border-radius: var(--radius-md);
    box-sizing: border-box;
    font-size: 15px;
    background: rgba(0, 0, 0, 0.25);
    color: var(--text-main);
    transition: all 0.25s ease;
}

.form-group input::placeholder {
    color: var(--text-dim);
}

.form-group input:focus {
    outline: none;
    border-color: var(--primary);
    box-shadow: 0 0 0 3px var(--primary-glow);
    background: rgba(0, 0, 0, 0.35);
}

.form-group input:-webkit-autofill {
    -webkit-box-shadow: 0 0 0 30px rgba(15, 15, 25, 0.9) inset !important;
    -webkit-text-fill-color: var(--text-main) !important;
}

.btn-primary {
    width: 100%;
    padding: 14px;
    background: var(--primary-gradient);
    color: white;
    border: none;
    border-radius: var(--radius-md);
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    margin-top: 8px;
    transition: all 0.25s ease;
    box-shadow: 0 4px 14px var(--primary-glow);
    letter-spacing: 1px;
    position: relative;
    overflow: hidden;
}

.btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 20px var(--primary-glow);
}

.btn-primary:active {
    transform: translateY(0) scale(0.98);
}

.btn-primary:disabled {
    background: var(--text-dim);
    box-shadow: none;
    cursor: not-allowed;
    transform: none;
}

.tabs {
    display: flex;
    margin-bottom: 24px;
    background: rgba(0, 0, 0, 0.15);
    border-radius: var(--radius-md);
    padding: 3px;
}

.tab {
    flex: 1;
    text-align: center;
    padding: 10px 12px;
    cursor: pointer;
    color: var(--text-sub);
    font-weight: 500;
    font-size: 14px;
    transition: all 0.25s ease;
    border-radius: 10px;
}

.tab.active {
    color: var(--text-main);
    background: var(--card-bg);
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);
}

.sms-group {
    display: flex;
    gap: 12px;
}
.sms-group input { flex: 1; }
.btn-sms {
    width: 110px;
    background: rgba(0, 0, 0, 0.25);
    color: var(--primary);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-md);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    flex-shrink: 0;
}
.btn-sms:hover {
    border-color: var(--primary);
    background: var(--btn-blue-bg);
}
.btn-sms:disabled {
    border-color: var(--border);
    color: var(--text-dim);
    cursor: not-allowed;
    background: transparent;
}

/* 使用说明按钮 */
.btn-instruction {
    margin-top: 28px;
    padding: 12px 32px;
    background: linear-gradient(135deg, #f59e0b, #ef4444);
    color: white;
    border: none;
    border-radius: var(--radius-full);
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    box-shadow: 0 4px 20px rgba(239, 68, 68, 0.3);
    transition: all 0.25s ease;
    animation: pulse 2.5s infinite;
}

.btn-instruction:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(239, 68, 68, 0.4);
}

@keyframes pulse {
    0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.35); }
    70% { box-shadow: 0 0 0 14px rgba(239, 68, 68, 0); }
    100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
}

/* ===================================================
   主应用
   =================================================== */
#app-area {
    display: none;
    flex-direction: row;
    height: 100%;
    max-width: 1200px;
    margin: 0 auto;
    background-color: transparent;
    position: relative;
}

.main-content {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    position: relative;
}

/* 顶栏 */
.header {
    background: var(--header-bg);
    backdrop-filter: blur(24px) saturate(160%);
    -webkit-backdrop-filter: blur(24px) saturate(160%);
    padding: 32px 24px 14px 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--card-border);
    z-index: 10;
}

.header-title {
    font-size: 18px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--text-main);
}

.header-title i.fa-robot {
    color: var(--primary);
    font-size: 22px;
}

.btn-icon {
    background: none;
    border: none;
    color: var(--danger);
    font-size: 14px;
    font-weight: 500;
    padding: 8px 14px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    gap: 6px;
    background-color: var(--btn-danger-bg);
}
.btn-icon:hover {
    background-color: var(--btn-danger-hover);
    transform: translateY(-1px);
}

.btn-icon-blue {
    background: var(--btn-blue-bg);
    color: var(--primary);
}
.btn-icon-blue:hover {
    background: var(--btn-blue-hover);
}

.btn-tts-active {
    background: var(--primary) !important;
    color: white !important;
}
.btn-tts-active:hover {
    background: var(--primary);
    opacity: 0.9;
}

.header-actions {
    display: flex;
    gap: 6px;
    align-items: center;
}

.header-actions .btn-text {
    display: inline;
}

.btn-more-actions {
    display: none;
    background: none;
    border: none;
    color: var(--text-main);
    font-size: 20px;
    cursor: pointer;
    padding: 6px 12px;
    border-radius: 8px;
    transition: background 0.2s;
}
.btn-more-actions:active {
    background: var(--input-bg);
}

/* ===================================================
   聊天区域
   =================================================== */
.chat-container {
    flex: 1;
    overflow-y: auto;
    padding: 24px;
    display: flex;
    flex-direction: column;
    gap: 20px;
    position: relative;
    z-index: 1;
    scroll-behavior: smooth;
}

/* 消息行 */
.msg-wrapper {
    display: flex;
    flex-direction: column;
    max-width: 100%;
    width: 100%;
}
.msg-wrapper.user {
    align-items: flex-end;
}
.msg-wrapper.ai {
    align-items: flex-start;
}

.msg-row {
    display: flex;
    flex-direction: column;
    max-width: 88%;
    animation: msgIn 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes msgIn {
    from { opacity: 0; transform: translateY(16px) scale(0.97); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}

.msg-row.user, .msg-row.ai {
    align-self: flex-end;
    align-items: flex-end;
    width: 100%;
}

/* 消息气泡 */
.msg-bubble {
    padding: 14px 18px;
    border-radius: var(--radius-xl);
    font-size: 15px;
    line-height: 1.65;
    word-break: break-word;
    white-space: pre-wrap;
    position: relative;
    backdrop-filter: blur(16px) saturate(150%);
    -webkit-backdrop-filter: blur(16px) saturate(150%);
    max-width: 100%;
    width: 100%;
    box-sizing: border-box;
}

.msg-row.user .msg-bubble {
    background: var(--msg-user-bg);
    color: white;
    border-bottom-right-radius: 4px;
    box-shadow: 0 4px 16px var(--msg-user-shadow);
}

.msg-row.ai .msg-bubble {
    background: var(--msg-ai-bg);
    color: var(--text-main);
    border-bottom-left-radius: 4px;
    border: 1px solid var(--msg-ai-border);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.msg-row.ai.error .msg-bubble {
    background: rgba(239, 68, 68, 0.08);
    color: var(--danger);
    border: 1px solid rgba(239, 68, 68, 0.2);
}

.msg-time {
    font-size: 12px;
    color: var(--text-dim);
    margin-top: 6px;
    padding: 0 6px;
    display: flex;
    align-items: center;
    gap: 6px;
}

.msg-time .btn-action {
    cursor: pointer;
    color: var(--text-dim);
    transition: color 0.2s;
}
.msg-time .btn-action:hover {
    color: var(--primary);
}
.msg-time .btn-action.active {
    color: var(--warning);
}

.msg-time .btn-action.quote-btn:hover {
    color: var(--accent);
}

.quote-indicator {
    background: var(--btn-blue-bg);
    border-left: 3px solid var(--primary);
    padding: 8px 12px;
    margin-bottom: 8px;
    border-radius: 6px;
    font-size: 13px;
    color: var(--text-main);
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.quote-indicator .quote-label {
    color: var(--text-dim);
    font-size: 11px;
    margin-right: 6px;
}

.quote-indicator .quote-content {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.quote-indicator .btn-close-quote {
    cursor: pointer;
    color: var(--text-dim);
    font-size: 14px;
    padding: 2px 6px;
    border-radius: 4px;
    transition: all 0.2s;
    flex-shrink: 0;
}

.quote-indicator .btn-close-quote:hover {
    color: var(--danger);
    background: rgba(239, 68, 68, 0.1);
}

/* ===================================================
   输入区
   =================================================== */
.input-area {
    background: var(--card-bg);
    backdrop-filter: blur(24px) saturate(160%);
    -webkit-backdrop-filter: blur(24px) saturate(160%);
    padding: 12px 20px;
    padding-bottom: calc(12px + env(safe-area-inset-bottom));
    border-top: 1px solid var(--card-border);
    display: flex;
    flex-direction: column;
    gap: 8px;
    align-items: stretch;
    position: relative;
    z-index: 10;
}

.input-controls {
    display: flex;
    gap: 10px;
    align-items: flex-end;
}

.input-box {
    flex: 1;
    background: var(--input-bg);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-full);
    padding: 12px 18px;
    font-size: 15px;
    outline: none;
    transition: all 0.25s ease;
    max-height: 120px;
    resize: none;
    overflow-y: auto;
    line-height: 1.5;
    color: var(--text-main);
}

.input-box::placeholder {
    color: var(--text-dim);
}

.input-box:focus {
    border-color: var(--primary);
    box-shadow: 0 0 0 3px var(--primary-glow);
    background: rgba(20, 20, 40, 0.6);
}

.btn-send {
    background: var(--primary-gradient);
    color: white;
    border: none;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.25s ease;
    flex-shrink: 0;
    margin-bottom: 2px;
    box-shadow: 0 4px 14px var(--primary-glow);
}

.btn-send i { font-size: 18px; margin-left: -1px; }

.btn-send:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px var(--primary-glow);
}

.btn-send:active {
    transform: scale(0.95);
}

.btn-send:disabled {
    background: var(--text-dim);
    box-shadow: none;
    cursor: not-allowed;
    transform: none;
}

.btn-stop {
    background: var(--danger);
    color: white;
    border: none;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    display: none;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.25s ease;
    flex-shrink: 0;
    margin-bottom: 2px;
    box-shadow: 0 4px 14px rgba(239, 68, 68, 0.3);
}

.btn-stop i { font-size: 18px; }

.btn-stop:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(239, 68, 68, 0.4);
}

.btn-stop:active {
    transform: scale(0.95);
}

.btn-upload {
    background: transparent;
    color: var(--text-dim);
    border: none;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s;
    flex-shrink: 0;
    margin-bottom: 2px;
    font-size: 20px;
}

.btn-upload:hover {
    color: var(--primary);
    background: var(--btn-blue-bg);
}

/* ===================================================
   状态栏
   =================================================== */
.status-bar {
    background: var(--card-bg);
    border-top: 1px solid var(--card-border);
    padding: 10px 20px;
    display: none;
    flex-direction: column;
    gap: 8px;
    z-index: 5;
}

.status-info {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 14px;
    color: var(--primary);
    font-weight: 500;
}

.status-icon {
    font-size: 16px;
}

.progress-bar {
    width: 100%;
    height: 4px;
    background: rgba(255, 255, 255, 0.06);
    border-radius: 2px;
    overflow: hidden;
    position: relative;
}

.progress-bar-inner {
    height: 100%;
    width: 30%;
    background: var(--primary-gradient);
    border-radius: 2px;
    position: absolute;
    animation: progress-slide 1.5s infinite ease-in-out;
}

@keyframes progress-slide {
    0% { left: -30%; }
    100% { left: 100%; }
}

/* ===================================================
   远程执行状态指示器
   =================================================== */
.remote-status-idle,
.remote-status-executing {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 12px;
    font-weight: 500;
    margin-left: 10px;
    padding: 3px 10px;
    border-radius: var(--radius-full);
    vertical-align: middle;
}
.remote-status-idle {
    color: var(--text-dim);
    background: rgba(100, 116, 139, 0.12);
}
.remote-status-executing {
    color: var(--success);
    background: rgba(34, 197, 94, 0.12);
}

/* ===================================================
   侧边栏
   =================================================== */
.sidebar {
    width: 260px;
    background: var(--card-bg);
    backdrop-filter: blur(24px) saturate(160%);
    -webkit-backdrop-filter: blur(24px) saturate(160%);
    border-right: 1px solid var(--card-border);
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    z-index: 1000;
    transition: width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
    overflow: hidden;
    white-space: nowrap;
}

.sidebar.hidden {
    width: 0;
    border-right: none;
    opacity: 0;
}

.sidebar.hidden .session-list,
.sidebar.hidden > div:first-child,
.sidebar.hidden #batch-session-bar {
    display: none;
}

.sidebar-toggle-wrapper {
    position: absolute;
    left: 260px;
    top: 50%;
    transform: translateY(-50%);
    z-index: 1001;
    transition: left 0.3s ease;
}

.sidebar.hidden ~ .sidebar-toggle-wrapper {
    left: 0;
}

.sidebar-toggle-btn {
    background: var(--card-bg);
    backdrop-filter: blur(24px) saturate(160%);
    -webkit-backdrop-filter: blur(24px) saturate(160%);
    border: 1px solid var(--card-border);
    border-left: none;
    padding: 12px 8px;
    cursor: pointer;
    color: var(--text-main);
    font-size: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
    border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    box-shadow: 2px 0 12px rgba(0, 0, 0, 0.15);
}

.sidebar-toggle-btn:hover {
    background: var(--input-bg);
    color: var(--primary);
}

.session-list {
    flex: 1;
    overflow-y: auto;
    padding: 10px;
}

.session-list::-webkit-scrollbar {
    width: 4px;
}
.session-list::-webkit-scrollbar-thumb {
    background: var(--text-dim);
    border-radius: 2px;
}

.session-item {
    padding: 12px 14px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    margin-bottom: 4px;
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--text-main);
    transition: all 0.2s;
}

.session-item:hover {
    background: var(--input-bg);
}

.session-item.active {
    background: var(--btn-blue-bg);
    border: 1px solid rgba(99, 102, 241, 0.15);
    font-weight: 500;
}

.session-item i.fa-message {
    font-size: 16px;
    color: var(--text-dim);
}
.session-item.active i.fa-message {
    color: var(--primary);
}

.session-title {
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-size: 14px;
}

.btn-delete-session {
    color: var(--text-dim);
    cursor: pointer;
    padding: 4px;
    display: none;
    transition: color 0.2s;
}
.session-item:hover .btn-delete-session {
    display: block;
}
.btn-delete-session:hover {
    color: var(--danger);
}

.btn-batch-session {
    display: block;
    width: 100%;
    margin-top: 8px;
    padding: 8px;
    border: 1px solid var(--card-border);
    border-radius: var(--radius-sm);
    background: transparent;
    color: var(--text-dim);
    font-size: 13px;
    cursor: pointer;
    text-align: center;
    transition: all 0.2s;
}
.btn-batch-session:hover {
    background: var(--input-bg);
    color: var(--text-main);
}

.session-batch-checkbox {
    width: 16px;
    height: 16px;
    cursor: pointer;
    flex-shrink: 0;
    accent-color: var(--primary);
}

.btn-menu {
    display: none;
    background: none;
    border: none;
    font-size: 20px;
    color: var(--text-main);
    cursor: pointer;
    padding: 0 10px 0 0;
}

.sidebar-overlay {
    display: none;
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 999;
}

