    box-shadow: 0 4px 16px var(--msg-user-shadow);
}

.msg-row.ai .msg-bubble {
    background: var(--msg-ai-bg);
    color: var(--text-main);
    border-bottom-left-radius: 4px;
    border: 1px solid var(--msg-ai-border);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.msg-row.ai.error .msg-bubble {
    background: rgba(239, 68, 68, 0.08);
    color: var(--danger);
    border: 1px solid rgba(239, 68, 68, 0.2);
}

.msg-time {
    font-size: 12px;
    color: var(--text-dim);
    margin-top: 6px;
    padding: 0 6px;
    display: flex;
    align-items: center;
    gap: 6px;
}

.msg-time .btn-action {
    cursor: pointer;
    color: var(--text-dim);
    transition: color 0.2s;
}
.msg-time .btn-action:hover {
    color: var(--primary);
}
.msg-time .btn-action.active {
    color: var(--warning);
}

.msg-time .btn-action.quote-btn:hover {
    color: var(--accent);
}

.quote-indicator {
    background: var(--btn-blue-bg);
    border-left: 3px solid var(--primary);
    padding: 8px 12px;
    margin-bottom: 8px;
    border-radius: 6px;
    font-size: 13px;
    color: var(--text-main);
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.quote-indicator .quote-label {
    color: var(--text-dim);
    font-size: 11px;
    margin-right: 6px;
}

.quote-indicator .quote-content {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.quote-indicator .btn-close-quote {
    cursor: pointer;
    color: var(--text-dim);
    font-size: 14px;
    padding: 2px 6px;
    border-radius: 4px;
    transition: all 0.2s;
    flex-shrink: 0;
}

.quote-indicator .btn-close-quote:hover {
    color: var(--danger);
    background: rgba(239, 68, 68, 0.1);
}

/* ===================================================
   输入区
   =================================================== */
.input-area {
    background: var(--card-bg);
    backdrop-filter: blur(24px) saturate(160%);
    -webkit-backdrop-filter: blur(24px) saturate(160%);
    padding: 12px 20px;
    padding-bottom: calc(12px + env(safe-area-inset-bottom));
    border-top: 1px solid var(--card-border);
    display: flex;
    flex-direction: column;
    gap: 8px;
    align-items: stretch;
    position: relative;
    z-index: 10;
}

.input-controls {
    display: flex;
    gap: 10px;
    align-items: flex-end;
}

.input-box {
    flex: 1;
    background: var(--input-bg);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-full);
    padding: 12px 18px;
    font-size: 15px;
    outline: none;
    transition: all 0.25s ease;
    max-height: 120px;
    resize: none;
    overflow-y: auto;
    line-height: 1.5;
    color: var(--text-main);
}

.input-box::placeholder {
    color: var(--text-dim);
}

.input-box:focus {
    border-color: var(--primary);
    box-shadow: 0 0 0 3px var(--primary-glow);
    background: rgba(20, 20, 40, 0.6);
}

.btn-send {
    background: var(--primary-gradient);
    color: white;
    border: none;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.25s ease;
    flex-shrink: 0;
    margin-bottom: 2px;
    box-shadow: 0 4px 14px var(--primary-glow);
}

.btn-send i { font-size: 18px; margin-left: -1px; }

.btn-send:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px var(--primary-glow);
}

.btn-send:active {
    transform: scale(0.95);
}

.btn-send:disabled {
    background: var(--text-dim);
    box-shadow: none;
    cursor: not-allowed;
    transform: none;
}

.btn-stop {
    background: var(--danger);
    color: white;
    border: none;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    display: none;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.25s ease;
    flex-shrink: 0;
    margin-bottom: 2px;
    box-shadow: 0 4px 14px rgba(239, 68, 68, 0.3);
}

.btn-stop i { font-size: 18px; }

.btn-stop:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(239, 68, 68, 0.4);
}

.btn-stop:active {
    transform: scale(0.95);
}

.btn-upload {
    background: transparent;
    color: var(--text-dim);
    border: none;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s;
    flex-shrink: 0;
    margin-bottom: 2px;
    font-size: 20px;
}

.btn-upload:hover {
    color: var(--primary);
    background: var(--btn-blue-bg);
}

/* ===================================================
   状态栏
   =================================================== */
.status-bar {
    background: var(--card-bg);
    border-top: 1px solid var(--card-border);
    padding: 10px 20px;
    display: none;
    flex-direction: column;
    gap: 8px;
    z-index: 5;
}

.status-info {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 14px;
    color: var(--primary);
    font-weight: 500;
}

.status-icon {
    font-size: 16px;
}

.progress-bar {
    width: 100%;
    height: 4px;
    background: rgba(255, 255, 255, 0.06);
    border-radius: 2px;
    overflow: hidden;
    position: relative;
}

.progress-bar-inner {
    height: 100%;
    width: 30%;
    background: var(--primary-gradient);
    border-radius: 2px;
    position: absolute;
    animation: progress-slide 1.5s infinite ease-in-out;
}

@keyframes progress-slide {
    0% { left: -30%; }
    100% { left: 100%; }
}

/* ===================================================
   远程执行状态指示器
   =================================================== */
.remote-status-idle,
.remote-status-executing {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 12px;
    font-weight: 500;
    margin-left: 10px;
    padding: 3px 10px;
    border-radius: var(--radius-full);
    vertical-align: middle;
}
.remote-status-idle {
    color: var(--text-dim);
    background: rgba(100, 116, 139, 0.12);
}
.remote-status-executing {
    color: var(--success);
    background: rgba(34, 197, 94, 0.12);
}

/* ===================================================
   侧边栏
   =================================================== */
.sidebar {
    width: 260px;
    background: var(--card-bg);
    backdrop-filter: blur(24px) saturate(160%);
    -webkit-backdrop-filter: blur(24px) saturate(160%);
    border-right: 1px solid var(--card-border);
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    z-index: 1000;
    transition: width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
    overflow: hidden;
    white-space: nowrap;
}

.sidebar.hidden {
    width: 0;
    border-right: none;
    opacity: 0;
}

.sidebar.hidden .session-list,
.sidebar.hidden > div:first-child,
.sidebar.hidden #batch-session-bar {
    display: none;
}

.sidebar-toggle-wrapper {
    position: absolute;
    left: 260px;
    top: 50%;
    transform: translateY(-50%);
    z-index: 1001;
    transition: left 0.3s ease;
}

.sidebar.hidden ~ .sidebar-toggle-wrapper {
    left: 0;
}

.sidebar-toggle-btn {
    background: var(--card-bg);
    backdrop-filter: blur(24px) saturate(160%);
    -webkit-backdrop-filter: blur(24px) saturate(160%);
    border: 1px solid var(--card-border);
    border-left: none;
    padding: 12px 8px;
    cursor: pointer;
    color: var(--text-main);
    font-size: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
    border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    box-shadow: 2px 0 12px rgba(0, 0, 0, 0.15);
}

.sidebar-toggle-btn:hover {
    background: var(--input-bg);
    color: var(--primary);
}

.session-list {
    flex: 1;
    overflow-y: auto;
    padding: 10px;
}

.session-list::-webkit-scrollbar {
    width: 4px;
}
.session-list::-webkit-scrollbar-thumb {
    background: var(--text-dim);
    border-radius: 2px;
}

.session-item {
    padding: 12px 14px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    margin-bottom: 4px;
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--text-main);
    transition: all 0.2s;
}

.session-item:hover {
    background: var(--input-bg);
}

.session-item.active {
    background: var(--btn-blue-bg);
    border: 1px solid rgba(99, 102, 241, 0.15);
    font-weight: 500;
}

.session-item i.fa-message {
    font-size: 16px;
    color: var(--text-dim);
}
.session-item.active i.fa-message {
    color: var(--primary);
}

.session-title {
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-size: 14px;
}

.btn-delete-session {
    color: var(--text-dim);
    cursor: pointer;
    padding: 4px;
    display: none;
    transition: color 0.2s;
}
.session-item:hover .btn-delete-session {
    display: block;
}
.btn-delete-session:hover {
    color: var(--danger);
}

.btn-batch-session {
    display: block;
    width: 100%;
    margin-top: 8px;
    padding: 8px;
    border: 1px solid var(--card-border);
    border-radius: var(--radius-sm);
    background: transparent;
    color: var(--text-dim);
    font-size: 13px;
    cursor: pointer;
    text-align: center;
    transition: all 0.2s;
}
.btn-batch-session:hover {
    background: var(--input-bg);
    color: var(--text-main);
}

.session-batch-checkbox {
    width: 16px;
    height: 16px;
    cursor: pointer;
    flex-shrink: 0;
    accent-color: var(--primary);
}

.btn-menu {
    display: none;
    background: none;
    border: none;
    font-size: 20px;
    color: var(--text-main);
    cursor: pointer;
    padding: 0 10px 0 0;
}

.sidebar-overlay {
    display: none;
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 999;
}

/* ===================================================
   Toast / Alert
   =================================================== */
.alert {
    position: fixed;
    top: 20px;
    left: 50%;
    transform: translateX(-50%);
    padding: 12px 28px;
    border-radius: var(--radius-full);
    font-size: 14px;
    font-weight: 500;
    z-index: 9999;
    display: none;
    box-shadow: 0 8

edits.newText:
    box-shadow: 0 8px 24px rgba(0,0,0,0.2);
    animation: slideDown 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes slideDown {
    from { top: -50px; opacity: 0; transform: translateX(-50%) translateY(-10px); }
    to { top: 20px; opacity: 1; transform: translateX(-50%) translateY(0); }
}
.alert.error { background: var(--danger); color: white; }
.alert.success { background: var(--success); color: white; }

.loading-dots { display: inline-block; }
.loading-dots::after {
    content: '.';
    animation: dots 1.5s steps(5, end) infinite;
}
@keyframes dots { 0%, 20% { color: rgba(0,0,0,0); text-shadow: .25em 0 0 rgba(0,0,0,0), .5em 0 0 rgba(0,0,0,0); } 40% { color: inherit; text-shadow: .25em 0 0 rgba(0,0,0,0), .5em 0 0 rgba(0,0,0,0); } 60% { text-shadow: .25em 0 0 inherit, .5em 0 0 rgba(0,0,0,0); } 80%, 100% { text-shadow: .25em 0 0 inherit, .5em 0 0 inherit; } }

.msg-token {
    font-size: 11px;
    color: var(--text-dim);
    padding: 2px 8px;
    background: var(--btn-blue-bg);
    border-radius: 4px;
    margin-right: 4px;
}
.msg-token.in { background: rgba(34, 197, 94, 0.12); color: var(--success); }
.msg-token.out { background: rgba(245, 158, 11, 0.12); color: var(--warning); }

/* ===================================================
   消息折叠
   =================================================== */
.msg-collapse {
    position: relative;
}
.msg-collapse-body {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
}
.msg-collapse.expanded .msg-collapse-body {
    max-height: 5000px;
}
.msg-collapse-toggle {
    display: block;
    width: 100%;
    padding: 8px 14px;
    margin-top: 8px;
    margin-bottom: 8px;
    background: var(--input-bg);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-sm);
    color: var(--primary);
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
    text-align: center;
    box-sizing: border-box;
}
.msg-collapse-toggle:hover {
    background: var(--btn-blue-hover);
}
.msg-collapse-toggle i {
    margin-left: 4px;
    font-size: 11px;
    transition: transform 0.2s;
}
.msg-collapse.expanded .msg-collapse-toggle i {
    transform: rotate(180deg);
}

/* ===================================================
   Markdown
   =================================================== */
.md-code {
    background: rgba(0, 0, 0, 0.3);
    padding: 16px 18px;
    border-radius: var(--radius-sm);
    font-size: 13px;
    font-family: 'SF Mono', 'Menlo', 'Consolas', 'Monaco', monospace;
    overflow-x: auto;
    white-space: pre-wrap;
    word-break: break-all;
    margin: 14px 0;
    border: 1px solid var(--card-border);
    line-height: 1.65;
    tab-size: 4;
}
.md-code code {
    font-family: inherit;
    font-size: inherit;
    line-height: inherit;
}
.md-code-inline {
    background: rgba(0, 0, 0, 0.3);
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 13px;
    font-family: 'SF Mono', 'Menlo', 'Consolas', 'Monaco', monospace;
    border: 1px solid var(--card-border);
}
.md-h1, .md-h2, .md-h3 {
    margin: 20px 0 10px;
    font-weight: 600;
    line-height: 1.4;
    color: var(--text-main);
}
.md-h1 { font-size: 22px; margin-top: 8px; }
.md-h2 { font-size: 19px; border-bottom: 1px solid var(--card-border); padding-bottom: 8px; }
.md-h3 { font-size: 17px; }
.md-li {
    margin: 6px 0;
    padding-left: 6px;
    line-height: 1.6;
}
.md-hr {
    border: none;
    border-top: 1px solid var(--card-border);
    margin: 20px 0;
}
.md-blockquote {
    border-left: 3px solid var(--primary);
    padding: 12px 18px;
    margin: 14px 0;
    background: var(--btn-blue-bg);
    border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    color: var(--text-main);
    line-height: 1.6;
}
.msg-bubble a {
    color: var(--primary);
    text-decoration: none;
    font-weight: 500;
    transition: opacity 0.2s;
}
.msg-bubble a:hover {
    opacity: 0.8;
    text-decoration: underline;
}

/* ===================================================
   表格
   =================================================== */
.table-wrapper {
    overflow-x: auto;
    max-width: 100%;
    margin: 14px 0;
    -webkit-overflow-scrolling: touch;
    border-radius: var(--radius-sm);
    border: 1px solid var(--card-border);
}
.table-wrapper table {
    min-width: 100%;
    width: auto;
    border-collapse: collapse;
    font-size: 14px;
    line-height: 1.5;
    margin: 0;
    table-layout: auto;
}
.table-wrapper th,
.table-wrapper td {
    border: 1px solid var(--card-border);
    padding: 10px 14px;
    text-align: left;
    vertical-align: top;
    white-space: normal;
    overflow-wrap: break-word;
    word-break: break-word;
}
.table-wrapper thead th {
    background: var(--primary-gradient);
    color: #fff;
    font-weight: 600;
    position: sticky;
    top: 0;
    z-index: 1;
}
.table-wrapper tbody tr:nth-child(even) {
    background: rgba(128, 128, 128, 0.03);
}
.table-wrapper tbody tr:hover {
    background: rgba(128, 128, 128, 0.06);
}

/* ===================================================
   Modal
   =================================================== */
.modal-overlay {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.65); z-index: 2000; display: none;
    justify-content: center; align-items: center;
    backdrop-filter: blur(4px);
    animation: fadeIn 0.2s ease;
}
.modal-card {
    background: var(--card-bg);
    border-radius: var(--radius-lg);
    padding: 28px;
    backdrop-filter: blur(24px) saturate(160%);
    -webkit-backdrop-filter: blur(24px) saturate(160%);
    width: 90%;
    max-width: 400px;
    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3);
    color: var(--text-main);
    border: 1px solid var(--card-border);
}
.modal-card h3 {
    margin: 0 0 16px 0;
    font-size: 18px;
    font-weight: 600;
}
.modal-card textarea {
    width: 100%; padding: 14px;
    border: 1px solid var(--card-border);
    background: var(--input-bg);
    color: var(--text-main);
    border-radius: var(--radius-sm);
    box-sizing: border-box;
    resize: none;
    font-size: 15px;
    outline: none;
    font-family: inherit;
    transition: border-color 0.2s;
}
.modal-card textarea:focus {
    border-color: var(--primary);
}
.modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 20px;
}
.btn-cancel {
    padding: 10px 20px;
    background: rgba(255, 255, 255, 0.06);
    border: none;
    border-radius: var(--radius-sm);
    cursor: pointer;
    font-weight: 500;
    color: var(--text-sub);
    transition: background 0.2s;
}
.btn-cancel:hover {
    background: rgba(255, 255, 255, 0.1);
}
.btn-confirm {
    padding: 10px 20px;
    background: var(--primary-gradient);
    border: none;
    border-radius: var(--radius-sm);
    cursor: pointer;
    font-weight: 500;
    color: white;
    transition: all 0.2s;
}
.btn-confirm:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px var(--primary-glow);
}

/* ===================================================
   收藏列表
   =================================================== */
.favorites-list {
    max-height: 300px;
    overflow-y: auto;
    margin-top: 10px;
    text-align: left;
}
.favorite-item {
    background: rgba(0, 0, 0, 0.15);
    padding: 12px;
    border-radius: var(--radius-sm);
    margin-bottom: 8px;
    font-size: 14px;
    position: relative;
}
.favorite-time {
    font-size: 12px;
    color: var(--text-dim);
    margin-bottom: 4px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.btn-unfav {
    color: var(--text-dim);
    cursor: pointer;
    padding: 2px 6px;
    transition: color 0.2s;
}
.btn-unfav:hover { color: var(--danger); }

/* ===================================================
   图片预览
   =================================================== */
.image-preview-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.92);
    z-index: 9999;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    animation: fadeIn 0.25s ease;
}
.image-preview-img {
    max-width: 92%;
    max-height: 92%;
    object-fit: contain;
    border-radius: var(--radius-md);
    box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}
.image-preview-close {
    position: absolute;
    top: 24px;
    right: 32px;
    color: #fff;
    font-size: 40px;
    font-weight: 200;
    cursor: pointer;
    transition: opacity 0.2s;
    line-height: 1;
    z-index: 10000;
}
.image-preview-close:hover { opacity: 0.7; }

/* ===================================================
   批量删除操作栏
   =================================================== */
#batch-delete-bar {
    padding: 12px 20px;
    background: var(--card-bg);
    border-top: 1px solid var(--card-border);
    display: none;
    justify-content: space-between;
    align-items: center;
    z-index: 5;
}
#batch-delete-bar span {
    font-size: 14px;
    font-weight: 500;
}
#batch-delete-bar #batch-count {
    color: var(--primary);
}
#batch-delete-bar .btn-cancel,
#batch-delete-bar .btn-confirm {
    padding: 8px 16px;
    font-size: 13px;
}
#batch-delete-bar .btn-confirm {
    background: var(--danger);
}
#batch-delete-bar .btn-confirm:hover {
    background: #dc2626;
}

/* ===================================================
   滚动按钮
   =================================================== */
#scroll-buttons {
    transition: left 0.25s ease, right 0.25s ease;
}
.btn-scroll {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: var(--card-bg);
    backdrop-filter: blur(16px);
    border: 1px solid var(--card-border);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
    transition: all 0.2s;
    color: var(--text-main);
}
.btn-scroll:hover {
    background: var(--input-bg);
    border-color: var(--primary);
    color: var(--primary);
}

/* ===================================================
   消息内图片
   =================================================== */
.msg-bubble img {
    max-width: 100%;
    border-radius: var(--radius-sm);
    margin: 12px 0;
    display: block;
}
.msg-bubble p {
    margin: 12px 0;
    line-height: 1.7;
}
.msg-bubble ul,
.msg-bubble ol {
    margin: 12px 0;
