.btn-confirm {
    padding: 10px 20px;
    background: var(--primary-gradient);
    border: none;
    border-radius: var(--radius-sm);
    cursor: pointer;
    font-weight: 500;
    color: white;
    transition: all 0.2s;
}
.btn-confirm:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px var(--primary-glow);
}

/* 收藏 */
.favorites-list { max-height: 300px; overflow-y: auto; margin-top: 10px; text-align: left; }
.favorite-item {
    background: rgba(0, 0, 0, 0.15);
    padding: 12px;
    border-radius: var(--radius-sm);
    margin-bottom: 8px;
    font-size: 14px;
    position: relative;
}
.favorite-time {
    font-size: 12px;
    color: var(--text-dim);
    margin-bottom: 4px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.btn-unfav { color: var(--text-dim); cursor: pointer; padding: 2px 6px; transition: color 0.2s; }
.btn-unfav:hover { color: var(--danger); }

/* 图片预览 */
.image-preview-overlay {
    display: none;
    position: fixed; top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.92);
    z-index: 9999;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    animation: fadeIn 0.25s ease;
}
.image-preview-img {
    max-width: 92%;
    max-height: 92%;
    object-fit: contain;
    border-radius: var(--radius-md);
    box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}
.image-preview-close {
    position: absolute;
    top: 24px;
    right: 32px;
    color: #fff;
    font-size: 40px;
    font-weight: 200;
    cursor: pointer;
    transition: opacity 0.2s;
    line-height: 1;
    z-index: 10000;
}
.image-preview-close:hover { opacity: 0.7; }

/* 批量删除栏 */
#batch-delete-bar {
    padding: 12px 20px;
    background: var(--card-bg);
    border-top: 1px solid var(--card-border);
    display: none;
    justify-content: space-between;
    align-items: center;
    z-index: 5;
}
#batch-delete-bar span { font-size: 14px; font-weight: 500; }
#batch-delete-bar #batch-count { color: var(--primary); }
#batch-delete-bar .btn-cancel,
#batch-delete-bar .btn-confirm { padding: 8px 16px; font-size: 13px; }
#batch-delete-bar .btn-confirm { background: var(--danger); }
#batch-delete-bar .btn-confirm:hover { background: #dc2626; }

/* 滚动按钮 */
#scroll-buttons { transition: left 0.25s ease, right 0.25s ease; }
.btn-scroll {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: var(--card-bg);
    backdrop-filter: blur(16px);
    border: 1px solid var(--card-border);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
    transition: all 0.2s;
    color: var(--text-main);
}
.btn-scroll:hover {
    background: var(--input-bg);
    border-color: var(--primary);
    color: var(--primary);
}

/* 消息内图文 */
.msg-bubble img { max-width: 100%; border-radius: var(--radius-sm); margin: 12px 0; display: block; }
.msg-bubble p { margin: 12px 0; line-height: 1.7; }
.msg-bubble ul, .msg-bubble ol { margin: 12px 0; padding-left: 24px; line-height: 1.6; }
.msg-bubble li { margin: 6px 0; line-height: 1.6; }
.msg-bubble strong { font-weight: 700; }
.msg-bubble em { font-style: italic; }

/* 自定义滚动条 */
.chat-container::-webkit-scrollbar,
.modal-card textarea::-webkit-scrollbar { width: 6px; }
.chat-container::-webkit-scrollbar-track,
.modal-card textarea::-webkit-scrollbar-track { background: transparent; }
.chat-container::-webkit-scrollbar-thumb,
.modal-card textarea::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.08); border-radius: 3px; }
.chat-container::-webkit-scrollbar-thumb:hover,
.modal-card textarea::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, 0.15); }

/* Cell 展开折叠 */
.table-wrapper td.cell-limit {
    position: relative;
    max-height: 4.8em;
    overflow: hidden;
    cursor: pointer;
}
.table-wrapper td.cell-limit::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 1.6em;
    background: linear-gradient(transparent, var(--card-bg));
    pointer-events: none;
}
.table-wrapper td.cell-limit.expanded { max-height: none; }
.table-wrapper td.cell-limit.expanded::after { display: none; }
.cell-toggle-btn {
    display: inline-block;
    margin-top: 2px;
    border: none;
    background: none;
    color: var(--primary);
    cursor: pointer;
    font-size: 12px;
    padding: 0;
}
.cell-toggle-btn:hover { text-decoration: underline; }

/* 响应式 - 移动端 */
@media (max-width: 768px) {
    #heart-canvas { display: none !important; }
    .btn-menu { display: block; }
    .chat-container { padding: 16px; gap: 16px; }
    .msg-row { max-width: 95%; }
    .msg-bubble { font-size: 14px; padding: 12px 14px; }
    .msg-bubble p { margin: 8px 0; }
    .md-code { font-size: 12px; padding: 12px 14px; }
    .md-code-inline { font-size: 12px; }
    .md-h1 { font-size: 19px; }
    .md-h2 { font-size: 17px; }
    .md-h3 { font-size: 15px; }

    .sidebar {
        position: absolute;
        left: -260px;
        top: 0;
        bottom: 0;
        transition: left 0.3s;
        box-shadow: 4px 0 20px rgba(0, 0, 0, 0.15);
    }
    .sidebar.open { left: 0; }
    .sidebar-overlay.open { display: block; }
    .sidebar-toggle-btn { display: none !important; }
    .sidebar-toggle-wrapper { display: none; }
    #app-area { max-width: 100%; }

    .header { padding: 28px 16px 12px 16px; position: relative; }
    .btn-more-actions { display: block; }
    .header-actions {
        display: none;
        position: absolute;
        top: 56px;
        right: 16px;
        background: var(--card-bg);
        backdrop-filter: blur(24px) saturate(160%);
        flex-direction: column;
        padding: 8px;
        border-radius: var(--radius-md);
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
        border: 1px solid var(--card-border);
        z-index: 1001;
        gap: 4px;
        min-width: 160px;
    }
    .header-actions.open { display: flex; }
    .header-actions .btn-text { display: inline; }
    .btn-icon {
        padding: 10px 16px;
        width: 100%;
        justify-content: flex-start;
        box-sizing: border-box;
    }

    .table-wrapper th, .table-wrapper td { padding: 6px 8px; font-size: 12px; }
    .table-wrapper table { font-size: 12px; }

    .input-area { padding: 10px 14px; padding-bottom: calc(10px + env(safe-area-inset-bottom)); }
}

@media (min-width: 769px) {
    .sidebar-toggle-wrapper { display: block; }
    .sidebar-toggle-btn { display: flex; }
}
